<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {money,type Plan} from '../lib/commercial';import Icon from './Icon.vue';const plans=ref<Plan[]>([]);const error=ref('');const latest=computed(()=>{const m=new Map<string,Plan>();for(const p of plans.value)if(!m.has(p.key)||m.get(p.key)!.version<p.version)m.set(p.key,p);return [...m.values()];});onMounted(async()=>{try{const r=await fetch('/api/public/plans');if(!r.ok)throw new Error('Plans are temporarily unavailable.');const d:any=await r.json();plans.value=d.plans;}catch(e:any){error.value=e.message;}});
</script>
<template><div class="pricing-intro"><div class="eyebrow">A STARTING POINT. ROOM TO GROW.</div><h1>Great support starts with a plan.</h1><p>Feature plans and AI usage stay separate. Choose hosted prepaid AI or bring your own provider on eligible plans.</p><span class="pill sample mt-5">Early access · payment providers not connected</span></div><p v-if="error" class="form-error">{{error}}</p><div class="plan-grid public-plans"><article v-for="p in latest" :key="p.id" class="panel plan-card"><h2>{{p.name}}</h2><p>{{p.description}}</p><div class="plan-price">{{money(p.priceMinor,p.currency)}}<span>/ {{p.intervalDays}} days</span></div><ul><li><Icon name="check" :size="15"/>{{p.limits.seats}} team members</li><li><Icon name="check" :size="15"/>{{p.limits.conversations.toLocaleString()}} retained conversations</li><li><Icon name="check" :size="15"/>{{p.limits.sources}} knowledge sources</li><li><Icon :name="p.features.byok?'check':'x'" :size="15"/>BYOK provider connections</li><li><Icon :name="p.features.memory?'check':'x'" :size="15"/>Optional customer memory</li></ul><a href="/app/#billing" class="button primary">{{p.priceMinor?'Explore this plan':'Start with Free'}}<Icon name="arrow" :size="15"/></a></article></div><div class="pricing-footnote"><h2>A fairer way to fund intelligence.</h2><p>Hosted AI draws from prepaid credit, using model rates set by the platform owner. BYOK means no Sahdev token charge; your provider’s charges and your plan’s feature, capacity, and abuse limits still apply. No automatic model fallback can spend your hosted balance.</p></div></template>
